ALTER TABLE vehicles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS runtime_access ON vehicles;
DROP POLICY IF EXISTS tenant_guard ON vehicles;
CREATE POLICY runtime_access ON vehicles USING (true) WITH CHECK (true);
CREATE POLICY tenant_guard ON vehicles AS RESTRICTIVE USING (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), ''))) WITH CHECK (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), '')));
ALTER TABLE remote_commands ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS runtime_access ON remote_commands;
DROP POLICY IF EXISTS tenant_guard ON remote_commands;
CREATE POLICY runtime_access ON remote_commands USING (true) WITH CHECK (true);
CREATE POLICY tenant_guard ON remote_commands AS RESTRICTIVE USING (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), ''))) WITH CHECK (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), '')));
