CREATE POLICY runtime_access ON command_reports USING (true) WITH CHECK (true);
CREATE POLICY tenant_guard ON command_reports AS RESTRICTIVE USING (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), ''))) WITH CHECK (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), '')));
ALTER TABLE telemetry_samples ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS runtime_access ON telemetry_samples;
DROP POLICY IF EXISTS tenant_guard ON telemetry_samples;
CREATE POLICY runtime_access ON telemetry_samples USING (true) WITH CHECK (true);
CREATE POLICY tenant_guard ON telemetry_samples AS RESTRICTIVE USING (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), ''))) WITH CHECK (tenant_id = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), '')));
ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS runtime_access ON outbox_events;
DROP POLICY IF EXISTS tenant_guard ON outbox_events;
CREATE POLICY runtime_access ON outbox_events USING (true) WITH CHECK (true);
CREATE POLICY tenant_guard ON outbox_events AS RESTRICTIVE USING (current_user = 'outbox_worker' OR (event_body::jsonb -> 'payload' ->> 'tenant_id') = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), ''))) WITH CHECK (current_user = 'outbox_worker' OR (event_body::jsonb -> 'payload' ->> 'tenant_id') = COALESCE(public.runtime_tenant_binding(), nullif(current_setting('app.tenant_id', true), '')));
